<script>
document.addEventListener('DOMContentLoaded',function(){
 const root=document.getElementById('schedule-calendar'); if(!root)return;
 const schedulePane=document.getElementById('schedule'); if(schedulePane && root.parentElement!==schedulePane) schedulePane.prepend(root);
 root.querySelectorAll('.schedule-event').forEach(card=>{const range=card.querySelector('span')?.textContent||'';const start=range.slice(0,5),end=range.slice(-5);const minutes=value=>{const parts=value.split(':').map(Number);return parts[0]*60+parts[1];};const top=Math.max(0,(minutes(start)-480)*0.8),height=Math.max(24,(minutes(end)-minutes(start))*0.8);card.style.top=`${56+top}px`;card.style.height=`${height}px`;});
