 const scheduleUpdateTemplate="{{ route('odontologia.odontologos.schedules.update', [$odontologo, '__ID__']) }}";
 const scheduleCancelTemplate="{{ route('odontologia.odontologos.schedules.cancel', [$odontologo, '__ID__']) }}";
 const blockUpdateTemplate="{{ route('odontologia.odontologos.blocks.update', [$odontologo, '__ID__']) }}";
 const oldTab=document.querySelector('[data-bs-target="#schedule"]'); if(oldTab){oldTab.addEventListener('click',()=>{root.style.display=window.matchMedia('(min-width: 992px)').matches?'grid':'block';});}
 document.querySelectorAll('[data-bs-toggle="tab"]').forEach(tab=>{if(tab!==oldTab)tab.addEventListener('click',()=>{root.style.display='none';});});
 const oldPane=document.getElementById('schedule'); if(oldPane){const legacy=oldPane.querySelector(':scope > .row');if(legacy)legacy.style.display='none';}
 const daySelect=document.getElementById('calendar-mobile-day'), columns=[...root.querySelectorAll('[data-calendar-day]')];
 const today="{{ now(\App\Support\TenantContext::timezone())->toDateString() }}", canModifyPast=@json(auth()->user()?->hasRole('ADMINISTRADOR')===true);
 if(!canModifyPast){root.querySelectorAll('.schedule-hour-cell').forEach(cell=>{if((cell.dataset.date||'')<today){cell.disabled=true;cell.title='Fecha pasada: solo lectura';cell.setAttribute('aria-disabled','true');}});root.querySelectorAll('.schedule-event').forEach(card=>{const date=card.closest('[data-calendar-day]')?.dataset.calendarDay;if(date&&date<today){card.dataset.readonly='1';card.title=(card.title||'')+' · Fecha pasada: solo lectura';}});}
 function selectDay(){const v=daySelect?.value||columns[0]?.dataset.calendarDay; columns.forEach(c=>c.classList.toggle('is-mobile-selected',c.dataset.calendarDay===v));}
 if(daySelect){daySelect.addEventListener('change',selectDay);daySelect.value=columns.find(c=>c.dataset.calendarDay===new Date().toISOString().slice(0,10))?.dataset.calendarDay||columns[0]?.dataset.calendarDay;} selectDay();
 const applyMode=document.getElementById('calendar-apply-mode'), summary=document.getElementById('calendar-summary'), weekStart=document.getElementById('calendar-week-start'), weeksInput=document.getElementById('calendar-weeks'), periodFrom=document.getElementById('calendar-period-from'), periodTo=document.getElementById('calendar-period-to'), startInput=document.getElementById('calendar-start'), endInput=document.getElementById('calendar-end');
 const dayNames=['','Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
 root.querySelectorAll('.calendar-weekday-pill span').forEach((span,index)=>{span.textContent=dayNames[index+1]||span.textContent;});
 const startOfWeek=value=>{const d=new Date(value+'T00:00:00');const day=d.getDay()||7;d.setDate(d.getDate()-day+1);return d;};
 const refreshApplicationFields=()=>{const mode=applyMode?.value||'SEMANA';document.getElementById('calendar-weeks-wrap')?.classList.toggle('d-none',mode!=='SEMANAS');document.getElementById('calendar-period-from-wrap')?.classList.toggle('d-none',mode!=='PERIODO');document.getElementById('calendar-period-to-wrap')?.classList.toggle('d-none',mode!=='PERIODO');if(summary){const selected=[...root.querySelectorAll('.calendar-weekday:checked')].map(input=>Number(input.value));const labels=selected.map(day=>dayNames[day]);let dayText=labels.join(', ')||'ningún día';if(labels.length>1)dayText=labels.slice(0,-1).join(', ')+' y '+labels.at(-1);let range='la semana seleccionada';let jornadas=selected.length;if(mode==='SEMANAS'){const extra=(weeksInput?.value||'').split(/[,;\s]+/).filter(Boolean);range=`${1+extra.length} semanas concretas`;jornadas=selected.length*(1+extra.length);}if(mode==='PERIODO'&&periodFrom?.value&&periodTo?.value){range=`del ${periodFrom.value} al ${periodTo.value}`;const from=new Date(periodFrom.value+'T00:00:00'),to=new Date(periodTo.value+'T00:00:00');jornadas=0;for(const cursor=new Date(from);cursor<=to;cursor.setDate(cursor.getDate()+1))if(selected.includes(cursor.getDay()||7))jornadas++;}summary.textContent=`${dayText}, de ${document.getElementById('calendar-start')?.value||'--:--'} a ${document.getElementById('calendar-end')?.value||'--:--'}, ${range}. Se crearán ${jornadas} jornadas con ${jornadas} tramos.`;}};
 [applyMode,weekStart,weeksInput,periodFrom,periodTo,startInput,endInput].forEach(input=>input?.addEventListener('input',refreshApplicationFields));root.querySelectorAll('.calendar-weekday').forEach(input=>input.addEventListener('change',refreshApplicationFields));refreshApplicationFields();
 const editor=document.getElementById('calendar-editor-card'), scheduleForm=document.getElementById('calendar-schedule-form'), blockForm=document.getElementById('calendar-block-form'), title=document.getElementById('calendar-editor-title'), weekdays=[...root.querySelectorAll('.calendar-weekday')];
 const open=(date,hour,endHour=null)=>{if(!editor)return; const d=new Date(date+'T00:00:00'), end=endHour ?? Math.min(hour+1,20); document.getElementById('calendar-day-number').value=(d.getDay()||7); document.getElementById('calendar-date-start').value=date;document.getElementById('calendar-date-end').value=date;document.getElementById('calendar-exception-date').value=date;document.getElementById('calendar-date-visible').value=date;document.getElementById('calendar-start').value=String(hour).padStart(2,'0')+':00';document.getElementById('calendar-end').value=String(end>hour?end:hour+1).padStart(2,'0')+':00';document.getElementById('calendar-block-start').value=date;document.getElementById('calendar-block-end').value=date;weekdays.forEach(input=>input.checked=Number(input.value)===(d.getDay()||7));editor.classList.remove('d-none');editor.scrollIntoView({behavior:'smooth',block:'nearest'});};
 let dragStart=null, dragEnd=null, suppressClick=false;
 const finishDrag=(target)=>{const cell=target?.closest?.('.schedule-hour-cell');if(!dragStart || !cell)return;const start=dragStart,end=dragEnd||{date:cell.dataset.date,hour:Number(cell.dataset.hour)};dragStart=null;dragEnd=null;if(suppressClick && start.date===end.date){suppressClick=false;const from=Math.min(start.hour,end.hour),to=Math.max(start.hour,end.hour);open(start.date,from,to>from?to:from+1);}else{open(cell.dataset.date,Number(cell.dataset.hour));}};
 root.querySelectorAll('.schedule-hour-cell').forEach(cell=>{
   cell.addEventListener('pointerdown',event=>{dragStart={date:cell.dataset.date,hour:Number(cell.dataset.hour)};dragEnd=dragStart;});
   cell.addEventListener('pointerenter',()=>{if(dragStart){dragEnd={date:cell.dataset.date,hour:Number(cell.dataset.hour)};if(dragEnd.date===dragStart.date && dragEnd.hour!==dragStart.hour)suppressClick=true;}});
   cell.addEventListener('pointermove',()=>{if(dragStart){dragEnd={date:cell.dataset.date,hour:Number(cell.dataset.hour)};if(dragEnd.date===dragStart.date && dragEnd.hour!==dragStart.hour)suppressClick=true;}});
   cell.addEventListener('pointerup',event=>finishDrag(event.target));
   cell.addEventListener('click',()=>{if(suppressClick){suppressClick=false;return;}if(!dragStart)open(cell.dataset.date,Number(cell.dataset.hour));});
 });
 document.addEventListener('pointerup',event=>finishDrag(event.target));
 const setMethod=(form,method)=>{let input=form?.querySelector('input[name="_method"]');if(method){if(!input){input=document.createElement('input');input.type='hidden';input.name='_method';form.appendChild(input);}input.value=method;}else if(input)input.remove();};
 blockForm?.addEventListener('submit',()=>{let input=blockForm.querySelector('[name="motivo_pasado"]');if(!input){input=document.createElement('input');input.type='hidden';input.name='motivo_pasado';blockForm.appendChild(input);}input.value=document.getElementById('calendar-past-reason')?.value||'';});
 const close=()=>{if(editor)editor.classList.add('d-none');setMethod(scheduleForm,null);setMethod(blockForm,null);scheduleForm.action="{{ route('odontologia.odontologos.schedules.store', $odontologo) }}";blockForm.action="{{ route('odontologia.odontologos.blocks.store', $odontologo) }}";document.getElementById('calendar-scope-wrap')?.classList.add('d-none');document.getElementById('calendar-schedule-submit').textContent='Guardar horario';document.getElementById('calendar-schedule-cancel')?.classList.add('d-none');}; document.getElementById('calendar-editor-close')?.addEventListener('click',close);document.getElementById('calendar-editor-cancel')?.addEventListener('click',close);root.querySelectorAll('.calendar-cancel').forEach(b=>b.addEventListener('click',close));
 root.querySelectorAll('.schedule-event').forEach(card=>card.addEventListener('click',()=>{if(card.dataset.readonly==='1')return;const date=card.closest('[data-calendar-day]')?.dataset.calendarDay;if(!date)return;const range=card.querySelector('span')?.textContent||'08:00–09:00';const start=range.slice(0,5);const end=range.slice(-5);const wantedType=card.classList.contains('schedule-event-block')?'block':card.classList.contains('schedule-event-schedule')?'schedule':null;const event=calendarEvents.find(item=>item.type===wantedType && item.date===date && item.start===start);open(date,Number(start.slice(0,2)),Number(end.slice(0,2)));if(wantedType==='schedule'){scheduleForm.action=scheduleUpdateTemplate.replace('__ID__',String(event?.id||''));setMethod(scheduleForm,'PUT');document.getElementById('calendar-scope-wrap')?.classList.remove('d-none');document.getElementById('calendar-schedule-cancel')?.classList.remove('d-none');document.getElementById('calendar-schedule-submit').textContent='Actualizar horario';if(title)title.textContent='Editar horario';}else if(wantedType==='block'){document.querySelector('[data-calendar-mode="block"]')?.click();blockForm.action=blockUpdateTemplate.replace('__ID__',String(event?.id||''));setMethod(blockForm,'PUT');document.getElementById('calendar-block-start').value=date;document.getElementById('calendar-block-end').value=date;document.getElementById('calendar-reason').value=event?.detail||'';}}));
 document.getElementById('calendar-schedule-cancel')?.addEventListener('click',()=>{if(!confirm('¿Cancelar este horario según el alcance seleccionado?'))return;const id=scheduleForm.action.split('/').pop();scheduleForm.action=scheduleCancelTemplate.replace('__ID__',id);setMethod(scheduleForm,'PATCH');document.getElementById('calendar-schedule-submit').click();});
 document.getElementById('calendar-scope-select')?.addEventListener('change',event=>{document.getElementById('calendar-scope').value=event.target.value;});
 root.querySelectorAll('[data-calendar-mode]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-calendar-mode]').forEach(b=>b.classList.remove('active'));button.classList.add('active');const block=button.dataset.calendarMode==='block';scheduleForm.classList.toggle('d-none',block);blockForm.classList.toggle('d-none',!block);document.getElementById('calendar-weekdays')?.classList.toggle('d-none',block);if(title)title.textContent=block?'Configurar bloqueo o ausencia':'Configurar horario de atención';}));
});
</script>
@endpush
